    fun t(text: String, language: String): String {
        if (language == "English") return text
        val col = COL[language] ?: return text
        val direct = T[text]?.getOrNull(col)
        if (direct != null) return direct
        val normalized = text.replace('“', '"').replace('”', '"').replace('’', '\'').trim()
        val normMatch = T[normalized]?.getOrNull(col)
        if (normMatch != null) return normMatch
        if (normalized.contains("electricity", ignoreCase = true) && (normalized.contains("scam wave", ignoreCase = true) || normalized.contains("kyc", ignoreCase = true))) {
            val key = "Scam wave: fake electricity-bill and KYC \"update\" texts are spiking. Never pay or share an OTP through a texted link."
            T[key]?.getOrNull(col)?.let { return it }
        }
        return text
    }
